import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone

__author__ = 'Dariusz Rosinski'
__copyright__ = 'Copyright (C) 2018-2019, Nokia'
__email__ = 'dariusz.rosinski@nokia.com'


class ExitUesim(GenericUnixCommand):
    """Command for exiting UESIM state of RTG Controller."""

    _re_telnet_prompt = re.compile(r"telnet>", re.IGNORECASE)
    _re_exit_character = re.compile(r"(?P<EXIT_CHAR>\w*)\s*exit telnet")

    def __init__(self, connection, prompt=None, newline_chars=None, expected_prompt=r'toor4nsn@fzm-lsp-k2:.*#',
                 runner=None, target_newline="\n"):
        """
        Class for exiting UESIM state in rtg controller.

        :param connection:
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after quit command
        :param newline_chars:
        """
        super(ExitUesim, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                        runner=runner)
        self.target_newline = target_newline
        self.ret_required = False
        self._re_expected_prompt = self._calculate_prompt(expected_prompt)
        self.newline_after_command_string = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "\x1d"

    @property
    def command_string(self):
        """
        Getter for command_string.

        :return: String with command_string
        """
        if not self.__command_string:
            self.__command_string = self.build_command_string()
            self._cmd_escaped = re.compile(r"\^]", re.I)
        return self.__command_string

    @command_string.setter
    def command_string(self, command_string):
        """
        Setter for command_string.

        :param command_string: Stting with command to set.
        :return: None
        """
        self.__command_string = command_string
        self._cmd_escaped = re.compile(r"\^]", re.I)

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._search_escape_character(line)
            self._search_target_prompt(line)
        except ParsingDone:
            pass

    def _search_escape_character(self, line):
        if self._regex_helper.search_compiled(ExitUesim._re_exit_character, line):
            self.connection.sendline(f"{self._regex_helper.group('EXIT_CHAR')}\n")
            raise ParsingDone

    def _search_target_prompt(self, line):
        """
        Check that telnet prompt is in incoming line.

        :param line: Line to process,
        :return: None
        """
        if self._regex_helper.search_compiled(self._re_expected_prompt, line):
            if not self.done():
                self.set_result({})
                raise ParsingDone


